  6→# Interactive Dashboard Builder Skill
  7→
  8→Patterns and techniques for building self-contained HTML/JS dashboards with Chart.js, filters, interactivity, and professional styling.
  9→
 10→## HTML/JS Dashboard Patterns
 11→
 12→### Base Template
 13→
 14→Every dashboard follows this structure:
 15→
 16→```html
 17→<!DOCTYPE html>
 18→<html lang="en">
 19→<head>
 20→    <meta charset="UTF-8">
 21→    <meta name="viewport" content="width=device-width, initial-scale=1.0">
 22→    <title>Dashboard Title</title>
 23→    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.5.1" integrity="REDACTED" crossorigin="anonymous"></script>
 24→    <script src="https://cdn.jsdelivr.net/npm/chartjs-adapter-date-fns@3.0.0" integrity="REDACTED" crossorigin="anonymous"></script>
 25→    <style>
 26→        /* Dashboard styles go here */
 27→    </style>
 28→</head>
 29→<body>
 30→    <div class="dashboard-container">
 31→        <header class="dashboard-header">
 32→            <h1>Dashboard Title</h1>
 33→            <div class="filters">
 34→                <!-- Filter controls -->
 35→            </div>
 36→        </header>
 37→
 38→        <section class="kpi-row">
 39→            <!-- KPI cards -->
 40→        </section>
 41→
 42→        <section class="chart-row">
 43→            <!-- Chart containers -->
 44→        </section>
 45→
 46→        <section class="table-section">
 47→            <!-- Data table -->
 48→        </section>
 49→
 50→        <footer class="dashboard-footer">
 51→            <span>Data as of: <span id="data-date"></span></span>
 52→        </footer>
 53→    </div>
 54→
 55→    <script>
 56→        // Embedded data
 57→        const DATA = [];
 58→
 59→        // Dashboard logic
 60→        class Dashboard {
 61→            constructor(data) {
 62→                this.rawData = data;
 63→                this.filteredData = data;
 64→                this.charts = {};
 65→                this.init();
 66→            }
 67→
 68→            init() {
 69→                this.setupFilters();
 70→                this.renderKPIs();
 71→                this.renderCharts();
 72→                this.renderTable();
 73→            }
 74→
 75→            applyFilters() {
 76→                // Filter logic
 77→                this.filteredData = this.rawData.filter(row => {
 78→                    // Apply each active filter
 79→                    return true; // placeholder
 80→                });
 81→                this.renderKPIs();
 82→                this.updateCharts();
 83→                this.renderTable();
 84→            }
 85→
 86→            // ... methods for each section
 87→        }
