 94→
 95→### KPI Card Pattern
 96→
 97→```html
 98→<div class="kpi-card">
 99→    <div class="kpi-label">Total Revenue</div>
100→    <div class="kpi-value" id="kpi-revenue">$0</div>
101→    <div class="kpi-change positive" id="kpi-revenue-change">+0%</div>
102→</div>
103→```
104→
105→```javascript
106→function renderKPI(elementId, value, previousValue, format = 'number') {
107→    const el = document.getElementById(elementId);
108→    const changeEl = document.getElementById(elementId + '-change');
109→
110→    // Format the value
111→    el.textContent = formatValue(value, format);
112→
113→    // Calculate and display change
114→    if (previousValue && previousValue !== 0) {
115→        const pctChange = ((value - previousValue) / previousValue) * 100;
116→        const sign = pctChange >= 0 ? '+' : '';
117→        changeEl.textContent = `${sign}${pctChange.toFixed(1)}% vs prior period`;
118→        changeEl.className = `kpi-change ${pctChange >= 0 ? 'positive' : 'negative'}`;
119→    }
120→}
121→
122→function formatValue(value, format) {
123→    switch (format) {
124→        case 'currency':
125→            if (value >= 1e6) return `$${(value / 1e6).toFixed(1)}M`;
126→            if (value >= 1e3) return `$${(value / 1e3).toFixed(1)}K`;
127→            return `$${value.toFixed(0)}`;
128→        case 'percent':
129→            return `${value.toFixed(1)}%`;
130→        case 'number':
131→            if (value >= 1e6) return `${(value / 1e6).toFixed(1)}M`;
132→            if (value >= 1e3) return `${(value / 1e3).toFixed(1)}K`;
133→            return value.toLocaleString();
134→        default:
135→            return value.toString();
136→    }
137→}
138→```
