149→## Chart.js Integration
150→
151→### Line Chart
152→
153→```javascript
154→function createLineChart(canvasId, labels, datasets) {
155→    const ctx = document.getElementById(canvasId).getContext('2d');
156→    return new Chart(ctx, {
157→        type: 'line',
158→        data: {
159→            labels: labels,
160→            datasets: datasets.map((ds, i) => ({
161→                label: ds.label,
162→                data: ds.data,
163→                borderColor: COLORS[i % COLORS.length],
164→                backgroundColor: COLORS[i % COLORS.length] + '20',
165→                borderWidth: 2,
166→                fill: ds.fill || false,
167→                tension: 0.3,
168→                pointRadius: 3,
169→                pointHoverRadius: 6,
170→            }))
171→        },
172→        options: {
173→            responsive: true,
174→            maintainAspectRatio: false,
175→            interaction: {
176→                mode: 'index',
177→                intersect: false,
178→            },
179→            plugins: {
180→                legend: {
181→                    position: 'top',
182→                    labels: { usePointStyle: true, padding: 20 }
183→                },
184→                tooltip: {
185→                    callbacks: {
186→                        label: function(context) {
187→                            return `${context.dataset.label}: ${formatValue(context.parsed.y, 'currency')}`;
188→                        }
189→                    }
190→                }
191→            },
192→            scales: {
193→                x: {
194→                    grid: { display: false }
195→                },
196→                y: {
197→                    beginAtZero: true,
198→                    ticks: {
199→                        callback: function(value) {
200→                            return formatValue(value, 'currency');
201→                        }
202→                    }
203→                }
204→            }
205→        }
206→    });
207→}
208→```
209→
210→### Bar Chart
211→
212→```javascript
213→function createBarChart(canvasId, labels, data, options = {}) {
214→    const ctx = document.getElementById(canvasId).getContext('2d');
215→    const isHorizontal = options.horizontal || labels.length > 8;
216→
217→    return new Chart(ctx, {
218→        type: 'bar',
219→        data: {
220→            labels: labels,
221→            datasets: [{
222→                label: options.label || 'Value',
223→                data: data,
224→                backgroundColor: options.colors || COLORS.map(c => c + 'CC'),
225→                borderColor: options.colors || COLORS,
226→                borderWidth: 1,
227→                borderRadius: 4,
228→            }]
229→        },
230→        options: {
231→            responsive: true,
232→            maintainAspectRatio: false,
233→            indexAxis: isHorizontal ? 'y' : 'x',
234→            plugins: {
235→                legend: { display: false },
236→                tooltip: {
237→                    callbacks: {
238→                        label: function(context) {
239→                            return formatValue(context.parsed[isHorizontal ? 'x' : 'y'], options.format || 'number');
240→                        }
241→                    }
242→                }
243→            },
244→            scales: {
245→                x: {
246→                    beginAtZero: true,
247→                    grid: { display: isHorizontal },
248→                    ticks: isHorizontal ? {
249→                        callback: function(value) {
250→                            return formatValue(value, options.format || 'number');
251→                        }
252→                    } : {}
253→                },
254→                y: {
255→                    beginAtZero: !isHorizontal,
256→                    grid: { display: !isHorizontal },
257→                    ticks: !isHorizontal ? {
258→                        callback: function(value) {
259→                            return formatValue(value, options.format || 'number');
260→                        }
261→                    } : {}
262→                }
263→            }
264→        }
265→    });
266→}
267→```
268→
269→### Doughnut Chart
270→
271→```javascript
272→function createDoughnutChart(canvasId, labels, data) {
273→    const ctx = document.getElementById(canvasId).getContext('2d');
274→    return new Chart(ctx, {
275→        type: 'doughnut',
276→        data: {
277→            labels: labels,
278→            datasets: [{
279→                data: data,
280→                backgroundColor: COLORS.map(c => c + 'CC'),
281→                borderColor: '#ffffff',
282→                borderWidth: 2,
283→            }]
284→        },
285→        options: {
286→            responsive: true,
287→            maintainAspectRatio: false,
288→            cutout: '60%',
289→            plugins: {
290→                legend: {
291→                    position: 'right',
292→                    labels: { usePointStyle: true, padding: 15 }
293→                },
294→                tooltip: {
295→                    callbacks: {
296→                        label: function(context) {
297→                            const total = context.dataset.data.reduce((a, b) => a + b, 0);
298→                            const pct = ((context.parsed / total) * 100).toFixed(1);
299→                            return `${context.label}: ${formatValue(context.parsed, 'number')} (${pct}%)`;
300→                        }
301→                    }
302→                }
303→            }
304→        }
305→    });
306→}
307→```
308→
309→### Updating Charts on Filter Change
310→
311→```javascript
312→function updateChart(chart, newLabels, newData) {
313→    chart.data.labels = newLabels;
314→
315→    if (Array.isArray(newData[0])) {
316→        // Multiple datasets
317→        newData.forEach((data, i) => {
318→            chart.data.datasets[i].data = data;
319→        });
320→    } else {
321→        chart.data.datasets[0].data = newData;
322→    }
323→
324→    chart.update('none'); // 'none' disables animation for instant update
325→}
326→```
