328→## Filter and Interactivity Implementation
329→
330→### Dropdown Filter
331→
332→```html
333→<div class="filter-group">
334→    <label for="filter-region">Region</label>
335→    <select id="filter-region" onchange="dashboard.applyFilters()">
336→        <option value="all">All Regions</option>
337→    </select>
338→</div>
339→```
340→
341→```javascript
342→function populateFilter(selectId, data, field) {
343→    const select = document.getElementById(selectId);
344→    const values = [...new Set(data.map(d => d[field]))].sort();
345→
346→    // Keep the "All" option, add unique values
347→    values.forEach(val => {
348→        const option = document.createElement('option');
349→        option.value = val;
350→        option.textContent = val;
351→        select.appendChild(option);
352→    });
353→}
354→
355→function getFilterValue(selectId) {
356→    const val = document.getElementById(selectId).value;
357→    return val === 'all' ? null : val;
358→}
359→```
360→
361→### Date Range Filter
362→
363→```html
364→<div class="filter-group">
365→    <label>Date Range</label>
366→    <input type="date" id="filter-date-start" onchange="dashboard.applyFilters()">
367→    <span>to</span>
368→    <input type="date" id="filter-date-end" onchange="dashboard.applyFilters()">
369→</div>
370→```
371→
372→```javascript
373→function filterByDateRange(data, dateField, startDate, endDate) {
374→    return data.filter(row => {
375→        const rowDate = new Date(row[dateField]);
376→        if (startDate && rowDate < new Date(startDate)) return false;
377→        if (endDate && rowDate > new Date(endDate)) return false;
378→        return true;
379→    });
380→}
381→```
382→
383→### Combined Filter Logic
384→
385→```javascript
386→applyFilters() {
387→    const region = getFilterValue('filter-region');
388→    const category = getFilterValue('filter-category');
389→    const startDate = document.getElementById('filter-date-start').value;
390→    const endDate = document.getElementById('filter-date-end').value;
391→
392→    this.filteredData = this.rawData.filter(row => {
393→        if (region && row.region !== region) return false;
394→        if (category && row.category !== category) return false;
395→        if (startDate && row.date < startDate) return false;
396→        if (endDate && row.date > endDate) return false;
397→        return true;
398→    });
399→
400→    this.renderKPIs();
401→    this.updateCharts();
402→    this.renderTable();
403→}
404→```
405→
406→### Sortable Table
407→
408→```javascript
409→function renderTable(containerId, data, columns) {
410→    const container = document.getElementById(containerId);
411→    let sortCol = null;
412→    let sortDir = 'desc';
413→
414→    function render(sortedData) {
415→        let html = '<table class="data-table">';
416→
417→        // Header
418→        html += '<thead><tr>';
419→        columns.forEach(col => {
420→            const arrow = sortCol === col.field
421→                ? (sortDir === 'asc' ? ' ▲' : ' ▼')
422→                : '';
423→            html += `<th onclick="sortTable('${col.field}')" style="cursor:pointer">${col.label}${arrow}</th>`;
424→        });
425→        html += '</tr></thead>';
426→
427→        // Body
428→        html += '<tbody>';
429→        sortedData.forEach(row => {
430→            html += '<tr>';
431→            columns.forEach(col => {
432→                const value = col.format ? formatValue(row[col.field], col.format) : row[col.field];
433→                html += `<td>${value}</td>`;
434→            });
435→            html += '</tr>';
436→        });
437→        html += '</tbody></table>';
438→
439→        container.innerHTML = html;
440→    }
441→
442→    window.sortTable = function(field) {
443→        if (sortCol === field) {
444→            sortDir = sortDir === 'asc' ? 'desc' : 'asc';
445→        } else {
446→            sortCol = field;
447→            sortDir = 'desc';
448→        }
449→        const sorted = [...data].sort((a, b) => {
450→            const aVal = a[field], bVal = b[field];
451→            const cmp = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
452→            return sortDir === 'asc' ? cmp : -cmp;
453→        });
454→        render(sorted);
455→    };
456→
457→    render(data);
458→}
459→```
