271→    // Common SDK options (without resume/prompt — those vary on retry)
272→    const baseOptions = {
273→      model: modelName,
274→      systemPrompt: body.system_prompt + skillInstruction + skillRestriction,
275→      allowedTools: [
276→        "Bash",
277→        "Read",
278→        "Write",
279→        "Edit",
280→        "Glob",
281→        "Grep",
282→        "Skill",
283→        "Task",
284→        "mcp__duckdb-data-agent__execute_sql",
285→        "mcp__duckdb-data-agent__ask_user_question",
286→        "mcp__duckdb-data-agent__render_chart",
287→        "mcp__duckdb-data-agent__create_skill",
288→        "mcp__duckdb-data-agent__save_memory",
289→        "mcp__duckdb-data-agent__recall_memories",
290→        "mcp__duckdb-data-agent__forget_memory",
291→      ] as string[],
292→      settingSources: ["project"] as SettingSource[],
293→      plugins: [],
294→      hooks: { PreToolUse: [skillAllowlistHook] },
295→      permissionMode: "bypassPermissions" as const,
296→      allowDangerouslySkipPermissions: true,
297→      maxTurns: 20,
298→      includePartialMessages: true,
299→      abortController,
300→      env: sdkEnv,
301→      stderr: (line: string) => {
302→        stderrLines.push(line);
303→        console.error(`[sidecar:cli] ${line}`);
304→      },
305→      ...(sdkAgents ? { agents: sdkAgents } : {}),
306→      ...(body.mcp_server_url
