 32→export function VegaLiteChartWidget({ spec }: VegaLiteChartWidgetProps) {
 33→  const containerRef = useRef<HTMLDivElement>(null);
 34→  const viewRef = useRef<{ finalize: () => void } | null>(null);
 35→  const { theme } = useTheme();
 36→  const isDark = theme === 'dark';
 37→  const { t } = useTranslation();
 38→  const [error, setError] = useState<string | null>(null);
 39→
 40→  useEffect(() => {
 41→    if (!containerRef.current || !spec) return;
 42→
 43→    setError(null);
 44→    viewRef.current?.finalize();
 45→    viewRef.current = null;
 46→
 47→    const config = isDark
 48→      ? { ...powerbiTheme, ...darkOverrides, axis: { ...powerbiTheme.axis, ...darkOverrides.axis }, legend: { ...powerbiTheme.legend, ...darkOverrides.legend }, title: { ...powerbiTheme.title, ...darkOverrides.title } }
 49→      : { ...powerbiTheme, background: 'transparent', view: { stroke: 'transparent' } };
 50→
 51→    const fullSpec = {
 52→      ...spec,
 53→      width: 'container',
 54→      autosize: { type: 'fit', contains: 'padding' },
 55→      config,
 56→    };
 57→
 58→    let cancelled = false;
 59→    embed(containerRef.current, fullSpec as never, {
 60→      actions: true,
 61→      renderer: 'svg',
 62→    })
 63→      .then((result) => {
 64→        if (cancelled) {
 65→          result.finalize();
 66→        } else {
 67→          viewRef.current = result;
 68→        }
 69→      })
 70→      .catch((err) => {
 71→        if (!cancelled) {
 72→          setError(err?.message || 'Failed to render Vega-Lite chart');
 73→        }
 74→      });
 75→
 76→    return () => {
 77→      cancelled = true;
 78→      viewRef.current?.finalize();
 79→      viewRef.current = null;
 80→    };
 81→  }, [spec, isDark]);
 82→
 83→  if (error) {
 84→    return (
 85→      <div style={{ padding: '1rem', textAlign: 'center', opacity: 0.6 }}>
 86→        {t('chartRenderError')}: {error}
 87→      </div>
 88→    );
 89→  }
 90→
 91→  return (
 92→    <div
 93→      ref={containerRef}
 94→      className="vega-lite-chart"
 95→      data-vegalite-spec={JSON.stringify(spec)}
 96→      style={{ width: '100%', minHeight: 400 }}
 97→    />
 98→  );
 99→}
