208→function formatDuration(ms: number): string {
209→  if (ms < 1000) return '<1s';
210→  const seconds = Math.round(ms / 1000);
211→  if (seconds < 60) return `${seconds}s`;
212→  const minutes = Math.floor(seconds / 60);
213→  const remainingSeconds = seconds % 60;
214→  return remainingSeconds > 0 ? `${minutes}m ${remainingSeconds}s` : `${minutes}m`;
215→}
