217→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
218→  const { t } = useTranslation();
219→  const { isStreaming, editMessage, deleteMessage, sendMessage, messages } = useAgent();
220→  const [isEditing, setIsEditing] = useState(false);
221→  const [editText, setEditText] = useState(message.content);
222→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
223→  const textareaRef = useRef<HTMLTextAreaElement>(null);
224→
225→  const isUser = message.role === 'user';
226→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
227→
228→  useEffect(() => {
229→    if (isEditing && textareaRef.current) {
230→      textareaRef.current.focus();
231→      textareaRef.current.selectionStart = textareaRef.current.value.length;
232→    }
233→  }, [isEditing]);
234→
235→  const handleEdit = () => {
236→    setEditText(message.content);
237→    setIsEditing(true);
238→    setIsConfirmingDelete(false);
239→  };
240→
241→  const handleCancelEdit = () => {
242→    setIsEditing(false);
243→    setEditText(message.content);
244→  };
245→
246→  const handleSaveEdit = () => {
247→    const trimmed = editText.trim();
248→    if (!trimmed || trimmed === message.content) {
249→      handleCancelEdit();
250→      return;
251→    }
252→    setIsEditing(false);
253→    editMessage(messageIndex, trimmed);
