261→  const handleKeyDown = (e: React.KeyboardEvent) => {
262→    if (e.key === 'Escape') {
263→      handleCancelEdit();
264→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
265→      e.preventDefault();
