273→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
274→      .map((s) => s.text || '')
275→      .join('');
276→    const remaining = message.content.slice(segmentedText.length);
277→    if (remaining.trim()) {
278→      streamingRemainder = remaining;
279→    }
280→  }
281→
282→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
283→  const isInAnswerPhase = message.currentPhase === 'answer';
284→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
285→
286→  const hasCharts = hasSegments && message.segments!.some(
287→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
288→  );
289→
290→  const answerBlockSegments = hasSegments
291→    ? message.segments!
292→        .filter((s) =>
293→          (s.type === 'answer' && s.text?.trim()) ||
294→          (s.type === 'subagent_end' && !s.chart_spec && !s.sqlResults?.length && s.text?.trim() && !hasAnswer) ||
295→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
296→          (s.type === 'subagent_end' && s.chart_spec)
297→        )
298→        .map((s) => {
299→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
300→            return { ...s, text: stripChartSpecBlocks(s.text) };
301→          }
302→          return s;
303→        })
304→        .filter((s) => {
305→          // Remove text segments that became empty after stripping chart blocks
306→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
307→            return false;
308→          }
309→          return true;
310→        })
311→    : [];
312→
313→  const questionSegments = hasSegments
