449→          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
450→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
451→            return displayText?.trim() ? (
