462→            const handleRetry = lastUserMsg ? () => sendMessage(lastUserMsg.content) : undefined;
463→            return <ErrorBlock key={`error-${i}`} errorMessage={seg.errorMessage || 'Unknown error'} onRetry={!isStreaming ? handleRetry : undefined} />;
464→          })}
465→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
466→            <span className="message-bubble__typing">{t('thinking')}</span>
467→          )}
468→        </div>
469→      ) : (
470→        <>
471→          <div className="message-bubble__content">
