  3→interface AgentCallbacks {
  4→  onTextChunk: (text: string) => void;
  5→  onThinkingDone: () => void;
  6→  onToolCall: (pending: ToolCallResult) => void;
  7→  onToolResult: (result: ToolCallResult) => void;
  8→  onSubagentStart?: (data: { id: string; name: string; prompt: string }) => void;
  9→  onSubagentThinking?: (data: { id: string; text: string }) => void;
 10→  onSubagentSqlQuery?: (data: { id: string; sql: string }) => void;
 11→  onSubagentSqlResult?: (data: { id: string; sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }) => void;
 12→  onSubagentEnd?: (data: { id: string; name: string; result?: string; thinking?: string; sql_results?: Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>; chart_spec?: { library?: 'plotly' | 'vegalite'; data: unknown[]; layout?: Record<string, unknown>; frames?: unknown[]; spec?: Record<string, unknown> } }) => void;
 13→  onDone: (sessionId: string | null) => void;
 14→  onError: (error: string) => void;
 15→  onUserQuestion?: (data: UserQuestionData) => void;
 16→}
 17→
 18→export type { AgentCallbacks };
 19→
 20→async function streamSSE(
 21→  response: Response,
 22→  callbacks: AgentCallbacks,
 23→  signal?: AbortSignal,
 24→): Promise<void> {
 25→  const reader = response.body?.getReader();
 26→  if (!reader) {
 27→    callbacks.onError('No response stream');
 28→    return;
 29→  }
 30→
 31→  let doneReceived = false;
 32→  const wrappedCallbacks: AgentCallbacks = {
 33→    ...callbacks,
 34→    onDone: (sessionId) => {
 35→      doneReceived = true;
 36→      callbacks.onDone(sessionId);
 37→    },
 38→    onError: (error) => {
 39→      doneReceived = true;
 40→      callbacks.onError(error);
 41→    },
 42→  };
 43→
 44→  try {
 45→    const decoder = new TextDecoder();
 46→    let buffer = '';
 47→    let eventType = '';
 48→
 49→    while (true) {
 50→      const { done, value } = await reader.read();
 51→      if (done) break;
 52→
 53→      buffer += decoder.decode(value, { stream: true });
 54→      const lines = buffer.split('\n');
 55→      buffer = lines.pop() ?? '';
 56→      for (const line of lines) {
 57→        if (line.startsWith('event: ')) {
 58→          eventType = line.slice(7).trim();
 59→        } else if (line.startsWith('data: ')) {
 60→          const data = line.slice(6);
 61→          try {
 62→            const parsed = JSON.parse(data);
 63→            handleSSEEvent(eventType, parsed, wrappedCallbacks);
 64→          } catch {
 65→            // Skip malformed JSON
 66→          }
 67→          eventType = '';
 68→        }
 69→      }
 70→    }
 71→
 72→    // Process any remaining data left in buffer after stream ends
 73→    if (buffer.trim()) {
 74→      const remainingLines = buffer.split('\n');
 75→      for (const line of remainingLines) {
 76→        if (line.startsWith('event: ')) {
 77→          eventType = line.slice(7).trim();
 78→        } else if (line.startsWith('data: ')) {
 79→          const data = line.slice(6);
 80→          try {
 81→            const parsed = JSON.parse(data);
 82→            handleSSEEvent(eventType, parsed, wrappedCallbacks);
 83→          } catch {
 84→            // Skip malformed JSON
 85→          }
 86→          eventType = '';
 87→        }
 88→      }
 89→    }
 90→
 91→    // Safety net: if stream ended without done/error, force done
 92→    if (!doneReceived) {
 93→      callbacks.onDone(null);
 94→    }
 95→  } catch (e: unknown) {
 96→    if (signal?.aborted) return;
 97→    const msg = e instanceof Error ? e.message : 'Connection failed';
 98→    callbacks.onError(msg);
 99→  }
100→}
