107→  conversationId?: string | null,
108→  callbacks?: AgentCallbacks,
109→  signal?: AbortSignal,
110→  userSessionId?: string,
111→  skills?: string[],
112→  chartLibrary?: string,
113→): Promise<void> {
114→  if (!callbacks) return;
