117→      method: 'POST',
118→      headers: {
119→        'Content-Type': 'application/json',
120→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
121→      },
122→      body: JSON.stringify({
123→        message,
124→        session_id: agentSessionId,
125→        conversation_id: conversationId,
126→        langfuse_session_id: langfuseSessionId,
127→        conversation_history: conversationHistory ?? [],
128→        ...(skills?.length ? { skills } : {}),
129→        chart_library: chartLibrary || 'plotly',
130→      }),
131→      signal,
132→    });
133→
134→    if (!response.ok) {
135→      const errorText = await response.text();
136→      callbacks.onError(`Server error: ${errorText}`);
137→      return;
138→    }
139→
140→    await streamSSE(response, callbacks, signal);
141→  } catch (e: unknown) {
142→    if (signal?.aborted) return;
143→    const msg = e instanceof Error ? e.message : 'Connection failed';
144→    callbacks.onError(msg);
145→  }
146→}
