189→function handleSSEEvent(
190→  eventType: string,
191→  data: Record<string, unknown>,
192→  callbacks: AgentCallbacks,
193→) {
194→  switch (eventType) {
195→    case 'thinking':
196→    case 'answer':
197→      callbacks.onTextChunk(data.text as string);
198→      break;
199→    case 'thinking_done':
200→      callbacks.onThinkingDone();
201→      break;
202→    case 'tool_call':
203→      callbacks.onToolCall({
204→        toolCallId: (data.id as string) ?? '',
205→        toolName: (data.name as string) ?? undefined,
206→        sql: (data.sql as string) ?? '',
207→        command: (data.command as string) ?? undefined,
208→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
209→        columns: [],
210→        rows: [],
211→        rowCount: 0,
212→      });
213→      break;
214→    case 'tool_result': {
215→      const result: ToolCallResult = {
216→        toolCallId: (data.id as string) ?? '',
217→        toolName: (data.name as string) ?? undefined,
218→        sql: (data.sql as string) ?? '',
219→        columns: (data.columns as string[]) ?? [],
220→        rows: (data.rows as Record<string, unknown>[]) ?? [],
221→        rowCount: (data.rowCount as number) ?? 0,
222→        error: (data.error as string) ?? undefined,
223→        output: (data.output as string) ?? undefined,
224→        rawContent: (data.content as string) ?? undefined,
225→        chart_spec: data.chart_spec
226→          ? {
227→              library: (data.chart_spec as Record<string, unknown>).library as 'plotly' | 'vegalite' | undefined,
228→              data: ((data.chart_spec as Record<string, unknown>).data as unknown[]) ?? [],
229→              layout: (data.chart_spec as Record<string, unknown>).layout as Record<string, unknown> | undefined,
230→              frames: (data.chart_spec as Record<string, unknown>).frames as unknown[] | undefined,
231→              spec: (data.chart_spec as Record<string, unknown>).spec as Record<string, unknown> | undefined,
232→            }
233→          : undefined,
234→        answerDurationMs: (data.answer_duration_ms as number) ?? undefined,
235→      };
236→      callbacks.onToolResult(result);
237→      break;
238→    }
239→    case 'subagent_start':
240→      callbacks.onSubagentStart?.({
241→        id: data.id as string,
242→        name: data.name as string,
243→        prompt: (data.prompt as string) ?? '',
244→      });
245→      break;
246→    case 'subagent_thinking':
247→      callbacks.onSubagentThinking?.({
248→        id: data.id as string,
249→        text: data.text as string,
250→      });
251→      break;
252→    case 'subagent_sql_query':
253→      callbacks.onSubagentSqlQuery?.({
254→        id: data.id as string,
255→        sql: data.sql as string,
256→      });
257→      break;
258→    case 'subagent_sql_result':
259→      callbacks.onSubagentSqlResult?.({
260→        id: data.id as string,
261→        sql: data.sql as string,
262→        columns: (data.columns as string[]) ?? undefined,
263→        rows: (data.rows as Record<string, unknown>[]) ?? undefined,
264→        rowCount: (data.rowCount as number) ?? undefined,
265→        error: (data.error as string) ?? undefined,
266→      });
267→      break;
268→    case 'subagent_end': {
269→      type ChartSpec = { library?: 'plotly' | 'vegalite'; data: unknown[]; layout?: Record<string, unknown>; frames?: unknown[]; spec?: Record<string, unknown> };
270→      // Backend sends chart_specs (array) for multi-chart support.
271→      // Fall back to legacy chart_spec (single object) for backwards compat.
272→      const rawSpecs = data.chart_specs as ChartSpec[] | undefined;
273→      const legacySpec = data.chart_spec as ChartSpec | undefined;
274→      const chartSpecs: ChartSpec[] = rawSpecs ?? (legacySpec ? [legacySpec] : []);
275→
276→      const saThinking = (data.thinking as string) ?? undefined;
277→
278→      if (chartSpecs.length > 0) {
279→        // Emit one callback per chart so each gets its own segment
280→        for (const spec of chartSpecs) {
281→          callbacks.onSubagentEnd?.({
282→            id: data.id as string,
283→            name: data.name as string,
284→            chart_spec: spec,
285→          });
286→        }
287→        // Emit text result separately (if any) so it doesn't get lost
288→        if (data.result || saThinking) {
289→          callbacks.onSubagentEnd?.({
290→            id: data.id as string,
291→            name: data.name as string,
292→            result: (data.result as string) ?? undefined,
293→            thinking: saThinking,
294→          });
295→        }
296→      } else {
297→        callbacks.onSubagentEnd?.({
298→          id: data.id as string,
299→          name: data.name as string,
300→          result: (data.result as string) ?? undefined,
301→          thinking: saThinking,
302→          sql_results: (data.sql_results as Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>) ?? undefined,
303→        });
304→      }
305→      break;
306→    }
307→    case 'user_question': {
308→      // Normalize options: the agent may send plain strings or {label, description} objects
309→      const rawOptions = (data.options as unknown[]) ?? [];
310→      const normalizedOptions: UserQuestionOption[] = (Array.isArray(rawOptions) ? rawOptions : []).map(
311→        (opt: unknown) => {
312→          if (typeof opt === 'string') return { label: opt };
313→          if (typeof opt === 'object' && opt !== null && 'label' in opt) return opt as UserQuestionOption;
314→          return { label: String(opt) };
315→        }
316→      );
317→      callbacks.onUserQuestion?.({
318→        questionId: data.question_id as string,
319→        question: data.question as string,
320→        options: normalizedOptions,
321→        multiSelect: (data.multi_select as boolean) ?? false,
322→      });
323→      break;
324→    }
325→    case 'done':
326→      callbacks.onDone((data.session_id as string) ?? null);
327→      break;
328→    case 'error':
329→      callbacks.onError((data.message as string) ?? 'Unknown error');
330→      break;
331→  }
332→}
