 1→import type { ChatMessage, ContentSegment, UserQuestionData, UserQuestionOption } from '../types';
 2→
 3→interface BackendMessage {
 4→  id: string;
 5→  role: string;
 6→  content: string;
 7→  metadata: string | null;
 8→}
 9→
10→/**
11→ * Convert backend message objects into ChatMessage[] for the UI.
12→ * Shared by ConversationContext.selectConversation and AgentContext stale-onDone refresh.
13→ */
14→export function buildChatMessages(messages: BackendMessage[]): ChatMessage[] {
15→  return messages.map((msg) => {
16→    if (msg.role !== 'assistant') {
17→      return { id: msg.id, role: 'user' as const, content: msg.content };
18→    }
19→
20→    // Try to restore segments from metadata
21→    let segments: ContentSegment[] | undefined;
22→    let durationMs: number | undefined;
23→    if (msg.metadata) {
24→      try {
25→        const meta = typeof msg.metadata === 'string' ? JSON.parse(msg.metadata) : msg.metadata;
26→        if (typeof meta?.durationMs === 'number') durationMs = meta.durationMs;
27→        if (Array.isArray(meta?.segments)) {
28→          segments = (meta.segments as Array<Record<string, unknown>>).map((seg) => {
29→            const s: ContentSegment = { type: seg.type as ContentSegment['type'] };
30→            if (seg.text) s.text = seg.text as string;
31→            if ((seg.toolCallId || seg.toolName) && seg.type !== 'user_question') {
32→              s.toolResult = {
33→                toolCallId: (seg.toolCallId as string) || '',
34→                toolName: seg.toolName as string,
35→                sql: (seg.sql as string) || '',
36→                columns: (Array.isArray(seg.columns) ? seg.columns : []) as string[],
37→                rows: (Array.isArray(seg.rows) ? seg.rows : []) as Record<string, unknown>[],
38→                rowCount: (seg.rowCount as number) || 0,
39→                error: seg.error as string | undefined,
40→                chart_spec: seg.chart_spec as ContentSegment['chart_spec'],
41→                ...(seg.toolInput ? { toolInput: seg.toolInput as Record<string, unknown> } : {}),
42→                ...(seg.output ? { output: seg.output as string } : {}),
43→              };
44→            }
45→            if (seg.subagentId) s.subagentId = seg.subagentId as string;
46→            if (seg.subagentName) s.subagentName = seg.subagentName as string;
47→            if (seg.thinking && seg.type === 'subagent_end') s.thinking = seg.thinking as string;
48→            if (seg.sqlResults) s.sqlResults = seg.sqlResults as ContentSegment['sqlResults'];
49→            if (seg.chart_spec && seg.type === 'subagent_end') {
50→              s.chart_spec = seg.chart_spec as ContentSegment['chart_spec'];
51→            }
52→            if (seg.questionData && seg.type === 'user_question') {
53→              const qd = seg.questionData as Record<string, unknown>;
54→              s.questionData = {
55→                questionId: (qd.questionId as string) || '',
56→                question: (qd.question as string) || '',
57→                options: (Array.isArray(qd.options) ? qd.options : []) as UserQuestionOption[],
58→                multiSelect: (qd.multiSelect as boolean) || false,
59→              } as UserQuestionData;
60→              if (seg.userAnswer) s.userAnswer = seg.userAnswer as string[];
61→              if (seg.userFreeText) s.userFreeText = seg.userFreeText as string;
62→              if (seg.answerDurationMs) s.answerDurationMs = seg.answerDurationMs as number;
63→            }
64→            return s;
65→          });
66→        }
67→      } catch {
68→        // metadata parse failed, fall through to default
69→      }
70→    }
71→
72→    // Fallback: single answer segment from content
73→    if (!segments) {
74→      segments = [{ type: 'answer' as const, text: msg.content }];
75→    }
76→
77→    return {
78→      id: msg.id,
79→      role: 'assistant' as const,
80→      content: msg.content,
81→      segments,
82→      ...(durationMs != null && { durationMs }),
83→    };
84→  });
85→}
