846→        pendingHistoryRef.current = remaining
847→          .filter((m) => m.role === 'user' || m.role === 'assistant')
848→          .map((m) => ({ role: m.role, content: m.content }));
849→        return remaining;
850→      });
851→
852→      // Persist the truncation to the backend
853→      if (convId) {
854→        fetch(`/api/conversations/${convId}/messages?from_sort_order=${messageIndex}`, {
855→          method: 'DELETE',
856→        }).catch(() => {
857→          // Best-effort: if this fails the UI is already updated
858→        });
859→        // Invalidate cache so switching back loads from backend
860→        messagesCacheRef.current.delete(convId);
861→      }
862→
863→      // Clear session so next message starts fresh
864→      sessionIdRef.current = null;
865→    },
866→    []
867→  );
868→
869→  const respondToQuestion = useCallback(
870→    async (questionId: string, answers: string[], freeText?: string) => {
871→      // Find the stream state that contains this question
872→      let targetState: StreamState | undefined;
873→      let targetConvId: string | null = null;
874→
875→      // Search all active streams for the question
876→      for (const [cid, state] of streamStatesRef.current) {
877→        if (state.segments.some(s => s.type === 'user_question' && s.questionData?.questionId === questionId)) {
878→          targetState = state;
879→          targetConvId = cid;
880→          break;
881→        }
882→      }
883→
884→      if (targetState) {
885→        const segIdx = targetState.segments.findIndex(
886→          s => s.type === 'user_question' && s.questionData?.questionId === questionId
887→        );
888→        if (segIdx !== -1) {
889→          targetState.segments[segIdx] = {
890→            ...targetState.segments[segIdx],
891→            userAnswer: answers,
892→            userFreeText: freeText,
893→          };
894→          targetState.messages = targetState.messages.map(m =>
895→            m.id === targetState!.assistantId
896→              ? { ...m, segments: [...targetState!.segments] }
897→              : m
898→          );
899→          if (activeConversationIdRef.current === targetConvId) {
900→            setMessages(targetState.messages);
901→          }
902→        }
903→      }
904→
905→      // POST to backend
906→      try {
907→        await fetch('/api/chat/respond', {
908→          method: 'POST',
909→          headers: {
910→            'Content-Type': 'application/json',
911→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
912→          },
913→          body: JSON.stringify({
914→            question_id: questionId,
915→            answers,
916→            free_text: freeText || null,
917→          }),
918→        });
919→      } catch (e) {
920→        console.error('Failed to respond to question:', e);
921→      }
922→    },
923→    [userSessionId]
924→  );
925→
926→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
927→    const outgoing = outgoingConversationId || null;
928→    const incoming = incomingConversationId || null;
929→    activeConversationIdRef.current = incoming;
930→
931→    // Save outgoing conversation's messages to cache (only if not streaming --
932→    // streaming conversations keep their state in streamStatesRef)
933→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
934→      const currentMsgs = messagesRef.current;
935→      if (currentMsgs.length > 0) {
936→        messagesCacheRef.current.set(outgoing, currentMsgs);
937→      }
938→    }
939→
940→    // Check if incoming conversation has an active stream (re-attachment)
941→    if (incoming) {
942→      const streamState = streamStatesRef.current.get(incoming);
943→      if (streamState) {
944→        // Re-attach: use live stream messages
945→        setMessages(streamState.messages);
946→        setIsStreaming(true);
947→        return;
948→      }
949→    }
950→
951→    // No active stream -- use backend data or cache
952→    let finalMsgs = msgs;
953→    if (incoming) {
954→      const cached = messagesCacheRef.current.get(incoming);
955→      if (cached && cached.length > 0 && cached.length > msgs.length) {
956→        finalMsgs = cached;
957→      }
958→      messagesCacheRef.current.delete(incoming);
959→    }
960→
961→    setMessages(finalMsgs);
962→    const hasStreamingMsg = finalMsgs.some(m => m.isStreaming);
963→    setIsStreaming(hasStreamingMsg);
964→    sessionIdRef.current = null;
965→    pendingHistoryRef.current = null;
966→  }, []);
967→
968→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
969→    const outgoing = outgoingConversationId || null;
970→    activeConversationIdRef.current = null;
971→
972→    // Save outgoing messages to cache if not streaming
973→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
974→      const currentMsgs = messagesRef.current;
975→      if (currentMsgs.length > 0) {
976→        messagesCacheRef.current.set(outgoing, currentMsgs);
977→      }
978→    }
979→
980→    setMessages([]);
981→    setIsStreaming(false);
982→    sessionIdRef.current = null;
983→    pendingHistoryRef.current = null;
984→  }, []);
985→
986→  return (
987→    <AgentContext.Provider
988→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion, streamingConversationIds }}
989→    >
990→      {children}
991→    </AgentContext.Provider>
992→  );
993→}
